"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/status-pages/variants/01-overview";
import View1 from "./components/status-pages/variants/02-incident";
const variants={"overview":View0,"incident":View1};
export interface ArtemisStatusPagesProps { className?: string; variant?: "overview" | "incident"; }
export function ArtemisStatusPages({className,variant="overview"}:ArtemisStatusPagesProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}
